/** Объяснения для формы и пособия; владельцы правил — mutateDualGenome,
 * TEMPORAL_TRAIT_INDICES и STRUCTURAL_BLOCKS. Здесь нет логики мутаций. */
export const MUTATION_DETAILS=Object.freeze({
 behavior:Object.freeze({role:'Наследственные настройки того, что житель чувствует и как учится: оценка энергии, здоровья и наполненности желудка, скорость обучения, забывание и работа памяти.',changes:'В новой физике сюда также входят наследуемые гены тела и пищеварения. Меняются гены этих настроек. Эта группа не меняет веса нейронных связей. Личные воспоминания и выученные поправки ребёнку не передаются.'}),
 attentionWeights:Object.freeze({role:'Малый мозг — диспетчер внимания. Пока житель выполняет действие или отдыхает, он решает, пора ли снова вызвать основной мозг и пересмотреть выбор.',changes:'Меняются численные веса связей и смещения нейронов. Добавление и удаление элементов управляется отдельной строкой структуры. За жизнь веса малого мозга не обучаются.'}),
 contextWeights:Object.freeze({role:'Контекст ситуации — часть основного мозга, которая собирает состояние тела, сводку видимых клеток, сведения личной памяти и текущего действия в общую картину ситуации. Эту картину используют при оценке доступных действий.',changes:'Меняются численные веса связей и смещения нейронов. Добавление и удаление элементов управляется отдельной строкой структуры. В течение жизни веса этой части могут обучаться.'}),
 attentionStructure:Object.freeze({role:'Структура малого мозга определяет его скрытые нейроны, слои и набор связей диспетчера внимания.',changes:'При создании генома ребёнка могут добавляться и удаляться нейроны и связи. Численные значения сохранившихся параметров эта группа не мутирует. Новые параметры получают начальные значения. Вероятность и сила отделены от мутаций весов малого мозга.'}),
 contextStructure:Object.freeze({role:'Структура контекста ситуации определяет, какими путями основной мозг объединяет сведения тела, окружения и памяти.',changes:'При создании генома ребёнка могут добавляться и удаляться скрытые нейроны, слои и связи. Значения сохранившихся весов эта группа не мутирует. Удаление элемента удаляет и его параметры. Новые параметры получают начальные значения; их последующие численные мутации задаёт строка весов контекста.'}),
 cells:Object.freeze({role:'Кодировщик клеток — небольшая сеть, которая одинаково обрабатывает каждую видимую клетку карты: пищу, воду, соседей и доступные сведения памяти. Из её результатов основной мозг получает сводку ближайшего окружения.',changes:'Меняются веса существующих связей и смещения нейронов. У текущей схемы скрытые нейроны, слои и набор связей изменяются отдельной структурной группой. Размеры внешних входов и выходов сохраняются. За жизнь основной мозг может обучать личные поправки к этим весам.'}),
 target:Object.freeze({role:'Проекция цели обрабатывает признаки одного рассматриваемого варианта: куда пойти или где выполнить действие, что там известно о пище и что помнит житель. Её результат сопоставляется с общей картиной ситуации.',changes:'Меняются веса существующих связей и смещения нейронов. У текущей схемы скрытые нейроны, слои и набор связей изменяются отдельной структурной группой. Размеры внешних входов и выходов сохраняются. За жизнь основной мозг может обучать личные поправки к этим весам.'}),
 operation:Object.freeze({role:'Проекция операции учитывает, что именно предлагается сделать: переместиться, подобрать, съесть, отдохнуть, родить или положить пищу. Один и тот же участок карты может получать разные оценки для разных действий.',changes:'Меняются веса существующих связей и смещения нейронов. У текущей схемы скрытые нейроны, слои и набор связей изменяются отдельной структурной группой. Размеры внешних входов и выходов сохраняются. За жизнь основной мозг может обучать личные поправки к этим весам.'}),
 direct:Object.freeze({role:'Прямая оценка — короткий путь от признаков рассматриваемого действия к его оценке. Например, известная пища в месте назначения может напрямую повысить или понизить оценку через соответствующий вес.',changes:'Меняются веса существующих связей и смещения нейронов. У текущей схемы скрытые нейроны, слои и набор связей изменяются отдельной структурной группой. Размеры внешних входов и выходов сохраняются. За жизнь основной мозг может обучать личные поправки к этим весам.'}),
 ...Object.fromEntries([['cells','Кодировщик клеток'],['target','Проекция цели'],['operation','Проекция операции'],['direct','Прямая оценка']].map(([key,name])=>[key+'Structure',Object.freeze({role:name+': скрытые нейроны, слои и связи этого блока.',changes:'Меняется при рождении ребёнка. Увеличение вероятности даёт больше структурных событий; увеличение силы даёт больший бюджет изменений за событие. Уменьшение делает события реже или меньше. Добавленный нейрон имеет входящую и исходящую связь, исходящий вес начинается с нуля. Значения сохранившихся весов меняются отдельной числовой группой; входы и выходы блока сохраняются.'})])),
});
export const MUTATION_HELP=Object.freeze({
 ...Object.fromEntries(Object.entries(MUTATION_DETAILS).map(([key,d])=>['mutation-block-'+key,['Что меняется в этом блоке?',d.role+'\n\n'+d.changes+'\n\n'+(key.endsWith('Structure')?'У структуры собственные наследуемые вероятность и сила.':'В текущей схеме каждый существующий вес/смещение меняется при рождении по своим A/r. У поведенческой группы меняются свойства, а не веса сети.')]])),
 'mutation-shape':['Форма числовой мутации A','Каждый существующий параметр включённого блока меняется при рождении. A управляет распределением величины: увеличение делает крупные сдвиги более обычными, уменьшение сосредоточивает их у минимального шага. Это не шанс мутации и не скорость личного обучения. Профиль наследуется и сам может мутировать.'],
 'mutation-ceiling':['Предел числовой мутации r','Задаёт верхний размер изменения относительно большего из модуля параметра и его опорного масштаба. Увеличение допускает более крупные сдвиги; уменьшение уменьшает верхний предел. Нулевые веса также меняются благодаря опорному масштабу и минимальному шагу. Это доля, а не вероятность события.'],
 'mutation-founders':['Стартовые значения и мутации потомков','Числовые A/r и структурные вероятность/сила задают профили случайных основателей нового мира. Числовые гены меняются при каждом рождении, структура — по отдельному шансу. Эти гены управляют изменениями при рождении их детей и затем тоже могут эволюционировать. Уже живущие особи от редактирования формы не меняются. Исходный активный профиль указан в полях и доступен для изменения. Загруженный геном сохраняет свои профили.'],
 'mutation-enabled':['Мутации потомков','Разрешает наследственные изменения именно этой группы при рождении ребёнка. Снятая галочка запрещает изменения выбранного типа и сохраняет его гены вероятности и силы. Отключение мутаций весов не мешает отдельной группе структуры удалять связи; отключение структуры не запрещает мутации весов. Общее выключение мутаций запрещает изменения всех групп. Личное обучение за жизнь управляется отдельно.'],
 'mutation-probability':['Начальная вероятность мутации','В строке весов шанс проверяется отдельно для каждого веса и смещения. В строке структуры — один раз для структурного события этой сети. Эти проверки и наследуемые вероятности независимы: оба типа изменений могут произойти при одном рождении. Собственные гены вероятности и силы группы также могут мутировать. Единица указана в заголовке: проценты либо доля единицы. Пустое поле задаёт случайное начальное значение.'],
 'mutation-strength':['Начальная сила мутации','В строке весов определяет максимальный случайный сдвиг численного параметра. В строке структуры задаёт бюджет добавления и удаления нейронов и связей; это отдельный наследуемый ген. Это не вероятность и не процент. Изменения ограничены пределами весов и структуры. Пустое поле задаёт случайное начальное значение; начальный диапазон не является потолком дальнейшей эволюции.']
});
